source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find each color's rectangular frame by its complete, one-cell-thick border.
    frames = []
    for color in range(1, 10):
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts:
            continue
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        border = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                  if r in (r0,r1) or c in (c0,c1)}
        if not all(grid[r][c] == color for r,c in border):
            continue
        # A frame's bounding box must contain no other colors.
        if any(grid[r][c] not in (0,color) for r in range(r0,r1+1) for c in range(c0,c1+1)):
            continue
        frames.append((r0,r1,c0,c1,color))
    sources = [f for f in frames if any(grid[r][c] != 0 for r in range(f[0]+1,f[1]) for c in range(f[2]+1,f[3]))]
    if not sources:
        return [row[:] for row in grid]
    src = sources[0]
    sr0,sr1,sc0,sc1,scol=src
    pattern = [[grid[r][c] == scol for c in range(sc0+1,sc1)] for r in range(sr0+1,sr1)]
    out = [row[:] for row in grid]
    for r0,r1,c0,c1,color in frames:
        if (r0,r1,c0,c1,color) == src:
            continue
        # Remove frames that cannot receive this template.
        if (r1-r0, c1-c0) != (sr1-sr0, sc1-sc0):
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    out[r][c] = 0
            continue
        for i, row in enumerate(pattern, start=1):
            for j, filled in enumerate(row, start=1):
                out[r0+i][c0+j] = color if filled else 0
    return out
'''
